<template>
  <div class="space-y-6">
    <PageHeader title="访问记录" description="查看节点上报的分钟聚合记录。仅保存域名级元数据，不记录正文、完整 URL 或凭据。"><template #actions><button @click="load" class="ios-btn-secondary">刷新</button></template></PageHeader>
    <p class="p-3 rounded-xl bg-blue-50 text-blue-800 text-sm">记录来自节点实际采集和批量上报。只展示域名级结果；未精确测量的流量和未确认的最终出口明确标示。内部中转和健康探测不计入用户访问。</p>
    <p class="text-xs text-gray-500">配置出口来自该版本核心日志的路由标签或出口组所选成员：它表示该节点按策略解析出的出口，不代表跨节点实际到达的出口节点。代理链表示配置关联，不证明流量抵达链尾。只有本节点直连路由能确认出口节点，也不代表已测量公网出口 IP 或目标响应成功。</p>
    <p class="text-xs text-gray-500">时间按 Agent 观察进入分钟桶；多行连接记录使用首次有效入站观察时间。配置版本、规则、实际出站和未知状态不同会分开记录。跨分钟仍存活的连接不会每分钟重复记为新连接；连接观察数不等于实时并发或请求次数。</p>
    <div class="ios-segmented-container inline-flex"><button v-for="tab in tabs" :key="tab.key" @click="switchTab(tab.key)" :class="['ios-segmented-item',activeTab===tab.key?'active':'']">{{ tab.label }}</button></div>
    <form @submit.prevent="search" class="panel-card p-5 grid sm:grid-cols-2 lg:grid-cols-3 gap-4 text-sm">
      <label>域名<input v-model="filters.domain" placeholder="example.com，不包含 URL" class="form-input-base mt-2" /></label>
      <label>用户<select v-model="filters.userId" class="form-input-base mt-2"><option value="">全部用户</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.username }}</option></select></label>
      <label>入口节点<select v-model="filters.nodeId" class="form-input-base mt-2"><option value="">全部节点</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option></select></label>
      <label>开始时间（{{ authState.timezone }}）<input v-model="fromLocal" type="datetime-local" class="form-input-base mt-2" /></label><label>结束时间（{{ authState.timezone }}）<input v-model="toLocal" type="datetime-local" class="form-input-base mt-2" /></label><div class="flex items-end"><button :disabled="loading" class="ios-btn-primary disabled:opacity-40">查询</button></div>
    </form>
    <div v-if="summary" class="grid sm:grid-cols-4 gap-4"><div class="panel-card p-4"><p class="text-xs text-gray-500">所选时间连接数</p><p class="font-semibold text-xl mt-2">{{ summary.connections }}</p></div><div class="panel-card p-4"><p class="text-xs text-gray-500">阻断次数</p><p class="font-semibold text-xl mt-2">{{ summary.blocked }}</p></div><div class="panel-card p-4"><p class="text-xs text-gray-500">已测量上传</p><TrafficValue :bytes="summary.uploadBytes" /><p v-if="summary.unknownTrafficConnections" class="text-xs text-amber-700 mt-2">含 {{ summary.unknownTrafficConnections }} 个流量未知连接</p></div><div class="panel-card p-4"><p class="text-xs text-gray-500">已测量下载</p><TrafficValue :bytes="summary.downloadBytes" /></div></div>
    <div v-if="accountSummary" class="panel-card p-4 text-sm"><h2 class="font-semibold mb-2">同一时间范围的已采样账户流量</h2><p v-if="accountSummary.observations"><TrafficValue :bytes="accountSummary.uploadBytes" /> 上传 / <TrafficValue :bytes="accountSummary.downloadBytes" /> 下载</p><p v-else class="text-gray-500">尚无账户计数样本</p><p class="text-xs text-gray-500 mt-2">上传/下载来自入口核心的账户累计计数差额；Xray WireGuard 使用设备专属路由标签，其他已认证账户使用用户计数。按凭据归属用户和设备，内部中转不重复计入。此处只沿用时间、用户和入口节点筛选，与域名及放行/阻断筛选独立；字节无法分配到域名，不代表完整节点网卡流量，尚未采样部分保持未知。</p></div><ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="loading && !records.length && !domains.length" /><EmptyState v-else-if="!total" title="没有匹配的访问记录" description="请检查时间、节点和用户筛选；尚未上报的数据不会显示。" />
    <DataTable v-else-if="activeTab !== 'stats'" min-width="min-w-[1250px]"><template #header><th>时间 / 版本</th><th>用户 / 设备</th><th>入口 / 协议</th><th>域名或目标 IP</th><th>结果 / 规则</th><th>配置出口</th><th>连接数</th><th>流量</th><th>详情</th></template><template #body><tr v-for="record in records" :key="record.id">
      <td class="p-4 text-xs">{{ formatTime(record.bucket) }}<p class="text-gray-500">#{{ record.revision }}</p></td><td class="text-xs">{{ userName(record.user_id) }}<p class="text-gray-500">{{ deviceName(record.device_id) }}</p></td><td class="text-xs">{{ nodeName(record.node_id) }}<p>{{ record.inbound_protocol }} · {{ record.network }}</p></td>
      <td class="font-mono text-xs max-w-56 break-all">{{ record.domain || record.target_ip }}<p class="text-gray-500">:{{ record.target_port }}</p></td><td class="text-xs"><StatusBadge :status="record.allowed ? 'active' : 'error'" /><p>{{ actionNames[record.action] }} · {{ ruleName(record.rule_id) }}</p></td>
      <td class="text-xs">{{ record.outbound_protocol || '未知' }}<p>{{ exitLabel(record) }}</p></td><td>{{ record.connections }}</td><td class="text-xs"><template v-if="record.upload_bytes !== null && record.download_bytes !== null"><TrafficValue :bytes="record.upload_bytes" /> / <TrafficValue :bytes="record.download_bytes" /></template><span v-else class="text-gray-500">—</span></td><td><button @click="selected = record; drawer = true" class="ios-action-btn-primary">详情</button></td>
    </tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <DataTable v-else><template #header><th>域名或 IP</th><th>连接数</th><th>阻断次数</th><th>已测量流量</th><th>测量状态</th></template><template #body><tr v-for="domain in domains" :key="domain.domain+'|'+domain.targetIp"><td class="p-4 font-mono text-sm">{{ domain.domain || domain.targetIp }}</td><td>{{ domain.connections }}</td><td>{{ domain.blocked }}</td><td><template v-if="domain.uploadBytes !== null && domain.downloadBytes !== null"><TrafficValue :bytes="domain.uploadBytes" /> / <TrafficValue :bytes="domain.downloadBytes" /></template><span v-else class="text-gray-500">—</span></td><td class="text-xs">{{ domain.unknownTrafficConnections ? domain.unknownTrafficConnections + ' 个连接流量未知' : '上报记录包含流量测量' }}</td></tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <FormDrawer v-model="drawer" title="访问记录详情" :show-footer="false"><dl v-if="selected" class="grid grid-cols-2 gap-4 text-sm"><dt>分钟时间桶</dt><dd>{{ formatTime(selected.bucket) }}</dd><dt>用户</dt><dd>{{ userName(selected.user_id) }}</dd><dt>设备</dt><dd>{{ deviceName(selected.device_id) }}</dd><dt>入口节点</dt><dd>{{ nodeName(selected.node_id) }}</dd><dt>入站协议</dt><dd>{{ selected.inbound_protocol }}</dd><dt>域名</dt><dd class="break-all">{{ selected.domain || '未知，使用目标 IP' }}</dd><dt>目标地址</dt><dd class="break-all">{{ selected.target_ip || '未上报 IP' }} :{{ selected.target_port }}</dd><dt>动作</dt><dd>{{ actionNames[selected.action] }}</dd><dt>规则</dt><dd>{{ ruleName(selected.rule_id) }}</dd><dt>代理链</dt><dd>{{ chainName(selected.chain_id) }}</dd><dt>配置出口</dt><dd>{{ outboundName(selected.outbound_id) }}<span v-if="selected.outbound_protocol"> · {{ selected.outbound_protocol }}</span></dd><dt>配置出口说明</dt><dd>{{ exitLabel(selected) }}；{{ exitSource(selected) }}</dd><dt>连接数</dt><dd>{{ selected.connections }}</dd><dt>上传 / 下载</dt><dd><template v-if="selected.upload_bytes !== null && selected.download_bytes !== null"><TrafficValue :bytes="selected.upload_bytes" /> / <TrafficValue :bytes="selected.download_bytes" /></template><span v-else class="text-gray-500">—</span></dd></dl></FormDrawer>
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted, watch } from 'vue'; import { useRoute } from 'vue-router'; import { accessAPI, type AccessRecord, type DomainRecord, type TrafficSummary, type AccessFilter, type AccountSummary } from '../api'; import { request, type Page } from '../../../app/apiClient'; import { authState, formatTime } from '../../../app/auth'; import { utcInput, localInput } from '../../../app/time'; import { userAPI, type ProxyUser, type ProxyDevice } from '../../users/api'; import { type NodeView } from '../../nodes/api'; import { proxyAPI, choices, type ProxyChain, type Outbound } from '../../proxy/api'; import { policyAPI, type PolicyRecord } from '../../routing/api'; import PageHeader from '../../../components/PageHeader.vue'; import DataTable from '../../../components/DataTable.vue'; import Pagination from '../../../components/Pagination.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import TrafficValue from '../../../components/TrafficValue.vue'; import FormDrawer from '../../../components/FormDrawer.vue'; import ErrorState from '../../../components/ErrorState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue'; import EmptyState from '../../../components/EmptyState.vue';
const accountSummary=ref<AccountSummary|null>(null); const route=useRoute(); const tabs=[{key:'all',label:'全部访问'},{key:'blocked',label:'已阻断'},{key:'stats',label:'域名统计'}]; const activeTab=ref(typeof route.query.tab==='string'&&tabs.some(tab=>tab.key===route.query.tab)?route.query.tab:'all');
const records=ref<AccessRecord[]>([]); const domains=ref<DomainRecord[]>([]); const users=ref<ProxyUser[]>([]); const devices=ref<ProxyDevice[]>([]); const nodes=ref<NodeView[]>([]); const rules=ref<PolicyRecord[]>([]); const chains=ref<ProxyChain[]>([]); const outbounds=ref<Outbound[]>([]); const summary=ref<TrafficSummary|null>(null); const filters=reactive({domain:'',userId:'',nodeId:''}); const fromLocal=ref(''); const toLocal=ref(''); const page=ref(1); const total=ref(0); const loading=ref(false); const error=ref(''); const drawer=ref(false); const selected=ref<AccessRecord|null>(null); const actionNames:Record<string,string>={Direct:'直连',Proxy:'代理',Block:'阻断'};
function nodeName(id?:string){return id?nodes.value.find(item=>item.id===id)?.name||id:'未知';} function userName(id?:string){return id?users.value.find(item=>item.id===id)?.username||id:'身份未知';} function deviceName(id?:string){return id?devices.value.find(item=>item.id===id)?.name||id:'未识别设备';} function ruleName(id?:string){return id?rules.value.find(item=>item.id===id)?.name||id:'未报告规则';} function chainName(id?:string){return id?chains.value.find(item=>item.id===id)?.name||id:'无代理链或未报告';} function outboundName(id?:string){return id?outbounds.value.find(item=>item.id===id)?.name||id:'未报告';}
function localDirectExit(record:AccessRecord){return record.allowed && record.action==='Direct' && record.outbound_protocol==='direct' && record.egress_known && record.final_egress_node_id===record.node_id && !record.chain_id;}
function exitLabel(record:AccessRecord){if(!record.allowed || record.action==='Block')return '已阻断，无出口';if(localDirectExit(record))return nodeName(record.final_egress_node_id)+' · 本节点直连';if(record.egress_known)return '历史上报：'+nodeName(record.final_egress_node_id)+'（未独立核验）';return '配置出口未确认';}
function exitSource(record:AccessRecord){if(!record.allowed || record.action==='Block')return '阻断记录不适用';if(localDirectExit(record))return '核心实际直连路由标签';if(record.egress_known)return '历史出口声明；配置拓扑不作为实际出口证据';return '该节点按策略解析出的配置出口，不代表跨节点实际到达的出口节点';}
function selectedFilter():AccessFilter{return {...filters,from:fromLocal.value?utcInput(fromLocal.value):undefined,to:toLocal.value?utcInput(toLocal.value):undefined};}
async function load(){if(loading.value)return;loading.value=true;try{const filter=selectedFilter();const result=activeTab.value==='stats'?await accessAPI.domains(filter,page.value):await accessAPI.list(filter,page.value,activeTab.value==='blocked');if(activeTab.value==='stats'){domains.value=result.items as DomainRecord[];records.value=[];}else{records.value=result.items as AccessRecord[];domains.value=[];}total.value=result.total;summary.value=await accessAPI.summary(filter); accountSummary.value=await accessAPI.accounts({ ...filter,domain:undefined });error.value='';}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function search(){page.value=1;load();} function changePage(value:number){page.value=value;load();} function switchTab(value:string){activeTab.value=value;page.value=1;load();}
async function initialize(){try{const [ns,us,ds,ps,cs,outs]=await Promise.all([choices((p,s)=>request<Page<NodeView>>('/nodes?page='+p+'&pageSize='+s)),choices((p,s)=>userAPI.list(p,'',s)),choices((p,s)=>userAPI.devices('',p,s)),choices((p,s)=>policyAPI.list(p,'',s)),choices((p,s)=>proxyAPI.chains('',p,s)),choices((p,s)=>proxyAPI.outbounds('',p,s))]);nodes.value=ns;users.value=us;devices.value=ds;rules.value=ps;chains.value=cs;outbounds.value=outs;fromLocal.value=localInput(new Date(Date.now()-24*3600000).toISOString());await load();}catch(e){error.value=(e as Error).message;}}
watch(()=>route.query.tab,value=>{if(typeof value==='string'&&tabs.some(tab=>tab.key===value))switchTab(value);});onMounted(initialize);
</script>
